sys_variable_value.value:
(function execute(inputs, outputs) {
    var headers = JSON.parse(inputs.responseHeaders);
    var cookies = headers['Set-Cookie'] || [];
    var accessTokenCookie = '';
    var refreshTokenCookie = '';

    for (var i = 0; i < cookies.length; i++) {
        if (cookies[i].indexOf('Access-Token=') === 0) {
            accessTokenCookie = cookies[i].split(';')[0];
        } else if (cookies[i].indexOf('Refresh-Token=') === 0) {
            refreshTokenCookie = cookies[i].split(';')[0];
        }
    }

    outputs.accesstokencookie = accessTokenCookie;
    outputs.refreshtokencookie = refreshTokenCookie;
})(inputs, outputs);

